  const ids=Object.keys(effectiveIngredients(m.i||{})),offers=ids.map(id=>OFFER_CACHE.byIngredient.get(id)).filter(Boolean),unique=[];const seen=new Set();for(const o of offers){if(seen.has(o.ingredient))continue;seen.add(o.ingredient);unique.push(o)}
