    const have=state.pantry[id]||0,buy=Math.max(0,q0-have);if(buy<=0)continue;const o=bestOfferForIngredient(id,retailer);if(!o)continue;
    let lineSaving=0;if(o.saving>0&&o.qty){const packs=Math.ceil(buy/o.qty);if(o.minPacks>1&&o.multiTotal&&o.standard){const groups=Math.floor(packs/o.minPacks);lineSaving=groups*Math.max(0,o.standard*o.minPacks-o.multiTotal)}else lineSaving=packs*o.saving;saving+=lineSaving}
