function migrateLegacyStorage(){
  if(store.get(PK))return;
  let oldProfiles=[];try{oldProfiles=JSON.parse(store.get(LEGACY_PK)||'[]')}catch(_){oldProfiles=[]}
  if(!Array.isArray(oldProfiles)||!oldProfiles.length)return;
  store.set(PK,JSON.stringify(oldProfiles));
  const oldActive=store.get(LEGACY_AK);if(oldActive)store.set(AK,oldActive);
  oldProfiles.forEach(p=>{const raw=store.get(legacySk(p.id));if(raw&&!store.get(sk(p.id)))store.set(sk(p.id),raw)})
}
