function adaptIngredient(id){
  let target=id;
  if(needDairyFree()&&SUBS[target]?.dairy)target=SUBS[target].dairy;
  if(needEggFree()&&SUBS[target]?.egg)target=SUBS[target].egg;
  if((needGlutenFree()||wheatFreeMode())&&SUBS[target]?.gluten)target=SUBS[target].gluten;
  if(state.dietPattern==='vegan'&&SUBS[target]?.vegan)target=SUBS[target].vegan;
  if(target==='oatmilk'&&needGlutenFree()){
    if(!hasAllergen('soy'))target='soymilk';else if(!hasAllergen('tree_nuts'))target='almondmilk';else target='coconutdrink'
  }
  return target
}
