function closeTrustModal(){document.getElementById('trustModal')?.classList.remove('show')}
function showToast(m){const t=document.getElementById('toast');if(!t)return;t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function bootstrapFarefully(){
  let loaded=false;
  try{loadCachedOfferData()}catch(e){console.warn('Farefully cached offer data skipped',e)}
  try{loaded=load()}catch(e){console.error('Farefully profile load failed',e);state=def();loaded=false}
  if(!state)state=def();
  try{applyAccessibility()}catch(e){console.warn('Farefully accessibility setup skipped',e)}
  try{if(loaded&&state.setupComplete&&state.tasteComplete&&state.dietComplete&&!state.plan.length)build();render()}catch(e){console.error('Farefully initial render failed',e)}
  if(!loaded){document.getElementById('welcome')?.classList.add('show')}
  else if(!state.setupComplete||!state.tasteComplete||!state.dietComplete){try{openSetup()}catch(e){console.error('Farefully setup open failed',e)}}
  setTimeout(()=>{Promise.allSettled([refreshWeeklyOfferFile(false),refreshLivePrices(false)]).then(()=>{try{OFFER_CACHE.key='';render()}catch(e){console.warn('Farefully post-offer refresh skipped',e)}})},150)
}



// CSP-safe handlers for elements created dynamically with innerHTML.
document.addEventListener('click',function(event){
  const el=event.target.closest('[data-ff-action]');
  if(!el)return;
  const action=el.dataset.ffAction;
  if(action==='open-recipe')openRecipe(Number(el.dataset.index));
  else if(action==='scroll-day')document.getElementById('m'+el.dataset.index)?.scrollIntoView();
  else if(action==='open-swap')openSwap(Number(el.dataset.index));
  else if(action==='toggle-basket')toggle(el.dataset.key);
  else if(action==='finish-profile'){closeProfiles();openSetup()}
  else if(action==='reset-profile')resetProfile(el.dataset.profileId);
  else if(action==='switch-profile')switchProfile(el.dataset.profileId);
  else if(action==='delete-profile')deleteProfile(el.dataset.profileId);
  else if(action==='pantry-category')setPantryCategory(el.dataset.category);
  else if(action==='quick-pantry')quickPantry(el.dataset.key);
  else if(action==='remove-pantry')removePantry(el.dataset.key);
  else if(action==='choose-swap')chooseSwap(el.dataset.mealId);
  else if(action==='edit-custom-recipe')editCustomRecipe(el.dataset.id);
  else if(action==='delete-custom-recipe')deleteCustomRecipe(el.dataset.id);
  else if(action==='remove-custom-ingredient')removeCustomIngredient(el.dataset.id);
  else if(action==='rebuild-offers')rebuildAroundOffers();
  else if(action==='refresh-offers')refreshOfferData(true);
  else if(action==='open-trust')openTrustModal();
  else if(action==='close-trust')closeTrustModal();
});

